sys_script.script:
(function () {
    var receiptSysId = current.getValue('material_receipt');
    var complianceScore = parseInt(current.getValue('compliance_score')) || 0;
    var qcResult = current.getValue('result');
    if (!receiptSysId) return;

    // Look up the material receipt
    var receiptGr = new GlideRecord('x_2056099_indust_0_mat_rcpt');
    if (!receiptGr.get(receiptSysId)) return;

    var orderSysId = receiptGr.getValue('procurement_order');
    var supplierSysId = receiptGr.getValue('supplier');
    if (!orderSysId || !supplierSysId) return;

    // Look up procurement order for delivery and quantity data
    var orderGr = new GlideRecord('x_2056099_indust_0_proc_ord');
    if (!orderGr.get(orderSysId)) return;

    // Calculate quality_score from QC compliance_score (0-100)
    // If compliance_score is 0, derive from result: pass=85, conditional_pass=60, fail=25
    var qualityScore = complianceScore;
    if (qualityScore === 0) {
        if (qcResult === 'pass') qualityScore = 85;
        else if (qcResult === 'conditional_pass') qualityScore = 60;
        else qualityScore = 25;
    }

    // Calculate delivery_score based on on-time delivery
    var deliveryScore = 75; // default
    var expectedDelivery = orderGr.getValue('expected_delivery');
    var receivedDateStr = receiptGr.getValue('received_date');
    if (expectedDelivery && receivedDateStr) {
        // expected_delivery is a Date field (YYYY-MM-DD), received_date is DateTime
        var expected = new GlideDateTime();
        expected.setValue(expectedDelivery + ' 23:59:59');
        var received = new GlideDateTime();
        received.setValue(receivedDateStr);

        var diffMs = received.getNumericValue() - expected.getNumericValue();
        if (diffMs <= 0) {
            deliveryScore = 95; // On time or early
        } else {
            var daysLate = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
            deliveryScore = Math.max(20, 95 - (daysLate * 5));
        }
    }

    // Calculate quantity_accuracy from ordered vs received
    var orderedQty = parseInt(orderGr.getValue('quantity')) || 0;
    var receivedQty = parseInt(receiptGr.getValue('quantity_received')) || 0;
    var quantityAccuracy = 75; // default
    if (orderedQty > 0) {
        quantityAccuracy = Math.round((Math.min(receivedQty, orderedQty) / orderedQty) * 100);
    }

    // Build materials summary
    var materialsOrdered = orderGr.getValue('materials_ordered') || '';
    var materialsSummary = materialsOrdered + ' - ' + receivedQty + ' received of ' + orderedQty + ' ordered';

    // Build amount summary
    var totalAmount = orderGr.getValue('total_amount') || '0';
    var amountSummary = 'Order Total: $' + totalAmount;

    // Build recommendations
    var recommendations = '';
    if (qcResult === 'pass') {
        recommendations = 'Quality check passed. Materials meet all specifications.';
    } else if (qcResult === 'conditional_pass') {
        recommendations = 'Conditional pass. Some materials require attention. Review defect details.';
    } else {
        recommendations = 'Quality check failed. Materials do not meet specifications. Consider returning shipment.';
    }
    if (deliveryScore < 70) {
        recommendations += ' Delivery was late - discuss delivery timelines with supplier.';
    }
    if (quantityAccuracy < 90) {
        recommendations += ' Quantity shortfall detected - follow up with supplier.';
    }

    // Create the procurement report with status "draft" first
    var reportGr = new GlideRecord('x_2056099_indust_0_proc_rpt');
    reportGr.initialize();
    reportGr.setValue('procurement_order', orderSysId);
    reportGr.setValue('material_receipt', receiptSysId);
    reportGr.setValue('quality_check', current.getUniqueValue());
    reportGr.setValue('supplier', supplierSysId);
    reportGr.setValue('quality_score', String(qualityScore));
    reportGr.setValue('delivery_score', String(deliveryScore));
    reportGr.setValue('quantity_accuracy', String(quantityAccuracy));
    reportGr.setValue('materials_summary', materialsSummary);
    reportGr.setValue('amount_summary', amountSummary);
    reportGr.setValue('recommendations', recommendations);
    reportGr.setValue('report_number', 'RPT-' + current.getValue('check_number'));
    reportGr.setValue('report_date', new GlideDateTime().getValue());
    reportGr.setValue('status', 'draft');
    var reportSysId = reportGr.insert();

    // Now update the report status to "submitted" to trigger the report-submission-rating flow
    // The flow triggers on record.updated where status VALCHANGES and status=submitted
    if (reportSysId) {
        var reportUpdate = new GlideRecord('x_2056099_indust_0_proc_rpt');
        if (reportUpdate.get(reportSysId)) {
            reportUpdate.setValue('status', 'submitted');
            reportUpdate.update();
        }
    }
})();
